-- Generated by tools/locales.py. To translate, change only the string after "=" and leave the comment lines
-- and the numbers alone; then run `python3 tools/locales.py check` (docs/translators/README.md).
-- Translators: Claude (AI-assisted, not yet reviewed by a native speaker), Codex (AI-assisted, not yet reviewed by a native speaker)
local addon_name, addon = ...

local L = LibStub("AceLocale-3.0"):NewLocale(addon_name, "esES", false, true)
if not L then return end

-- Human translators the About page credits (display names only; the AI is named in the header above).
L[0] = {}

addon.translation = {
-- a600e4ad English: Levels 1–70, every spec. From stealth: Premeditation, then Cheap Shot solo or
--     Garrote in a group, otherwise Ambush (with a dagger in the main hand). In combat: Riposte,
--     Slice and Dice from two combo points (renewed in its last two seconds), Eviscerate on a
--     target about to die, and at five points Rupture when it will last (not while Blade Flurry
--     cleaves), otherwise Eviscerate. Builds with Mutilate or Backstab (dagger) when the target is
--     not attacking you, otherwise Hemorrhage or Sinister Strike. Reminds you of missing poisons,
--     Kick, Blade Flurry and Adrenaline Rush, Cold Blood and Evasion. Expose Armor, Kidney Shot,
--     Feint, Vanish and positioning stay with you.
[1] = "Niveles 1–70, todas las especializaciones. Desde sigilo: Premeditación, y después Golpe bajo en solitario o Garrote en grupo; si no, Emboscada (con una daga en la mano principal). En combate: Contestación, Hacer picadillo desde dos puntos de combo (renovado en sus dos últimos segundos), Eviscerar sobre un objetivo a punto de morir y, con cinco puntos, Ruptura si va a durar (no mientras Aluvión de acero golpea a varios objetivos); si no, Eviscerar. Genera puntos con Mutilar o Puñalada (daga) cuando el objetivo no te está atacando; si no, con Hemorragia o Golpe siniestro. Te recuerda los venenos que faltan, Patada, Aluvión de acero y Subidón de adrenalina, Sangre fría y Evasión. Exponer armadura, Golpe en los riñones, Amago, Esfumarse y el posicionamiento quedan a tu cargo.",
-- 5f9b3940 English: Melee DPS (Wowhead)
-- Context: Name of a Built In (premade) rotation, shown in the rotation list and picker: Rogue, The
--     Burning Crusade Classic (variant key: DPS / Wowhead). Names in parentheses (guide or tool
--     such as Icy Veins, Wowhead, SimulationCraft, simulator, Hekili, Mobalytics, Warcraft Tavern)
--     are proper names and stay unchanged.
[2] = "DPS cuerpo a cuerpo (Wowhead)",
-- d6b11787 English: Levels 1–70, every spec, following Wowhead. Same stealth openers, builders and
--     reminders as the simulator version, but Slice and Dice starts from one combo point and every
--     five-point finisher is Eviscerate: no Rupture. Expose Armor, Kidney Shot, Feint, Vanish and
--     positioning stay with you. An alternative to the recommended simulator melee DPS premade, off
--     by default: enable it and disable that one, or raise its priority.
[3] = "Niveles 1–70, todas las especializaciones, según Wowhead. Las mismas aperturas desde sigilo, generadores y recordatorios que la versión de simulador, pero Hacer picadillo empieza desde un punto de combo y todo remate de cinco puntos es Eviscerar: sin Ruptura. Exponer armadura, Golpe en los riñones, Amago, Esfumarse y el posicionamiento quedan a tu cargo. Es una alternativa a la rotación integrada de DPS cuerpo a cuerpo de simulador recomendada, desactivada por defecto: actívala y desactiva la otra, o súbele la prioridad.",
-- f8f8f256 English: Melee damage for every Rogue specialization from level 1 to 60, built from Icy
--     Veins, Wowhead and Warcraft Tavern. The builder follows what you know: Mutilate (Sinister
--     Strike for the fifth point), Hemorrhage, Backstab when the target is not facing you, else
--     Sinister Strike. From Stealth it opens with Premeditation, Cheap Shot when solo, Garrote for
--     Subtlety on group elites, else Ambush or Garrote. It keeps Slice and Dice and Venom up, uses
--     Expose Armor in groups on elites when no warrior has five Sunders, then spends five points on
--     Rupture (Subtlety, long fights) or Eviscerate, and never builds past five. Reminders: poisons
--     on each weapon, Kick, Blade Flurry and Adrenaline Rush on packs and elites, Cold Blood,
--     Evasion, Feint, Thistle Tea and Preparation. Left to you: Vanish, Sprint, Kidney Shot, Blind,
--     Sap and positioning. Forever restricts combat data, so Rotation Master lists this premade for
--     reference and does not select it automatically yet.
[4] = "Daño cuerpo a cuerpo para todas las especializaciones de pícaro del nivel 1 al 60, basada en Icy Veins, Wowhead y Warcraft Tavern. El generador depende de lo que conozcas: Mutilar (Golpe siniestro para el quinto punto), Hemorragia, Puñalada cuando el objetivo no te mira y, si no, Golpe siniestro. Desde Sigilo abre con Premeditación, Golpe bajo en solitario, Garrote para Sutileza contra élites en grupo y, si no, Emboscada o Garrote. Mantiene Hacer picadillo y Veneno, usa Exponer armadura en grupo contra élites cuando ningún guerrero tiene cinco Hender armadura, y después gasta cinco puntos en Ruptura (Sutileza, combates largos) o Eviscerar, y nunca acumula más de cinco. Recordatorios: venenos en cada arma, Patada, Ráfaga con espada y Subidón de adrenalina contra grupos de enemigos y élites, Sangre fría, Evasión, Amago, Té de cardo y Preparación. Quedan a tu cargo: Esfumar, Correr, Golpe a los riñones, Ceguera, Zapar y el posicionamiento. Forever restringe los datos de combate, así que Rotation Master muestra esta rotación integrada como referencia y todavía no la selecciona automáticamente.",
-- 3333c1f0 English: Subtlety, Ambush build (Warcraft Tavern)
[5] = "Sutileza, build de Emboscada (Warcraft Tavern)",
-- 776899da English: Warcraft Tavern's Ambush/Cutthroat Subtlety build: Premeditation and Ambush on
--     every opener, Ambush again whenever Cutthroat allows it, Backstab from behind as the builder
--     (Hemorrhage when the target is facing you), Ghostly Strike on cooldown, and Slice and Dice
--     then Eviscerate at five points with no Rupture. Reminds you to Vanish for another Ambush on a
--     tanked boss. Choose it instead of the recommended Rogue premade if you took the Cutthroat
--     talents; it applies with Subtlety as your main talent tree and Cutthroat talented. Same
--     poison and cooldown reminders as the recommended premade. An alternative to the recommended
--     Rogue DPS premade, off by default: enable it and disable that one, or raise its priority.
[6] = "La build de Sutileza con Emboscada/Degollador de Warcraft Tavern: Premeditación y Emboscada en cada apertura, de nuevo Emboscada siempre que Degollador lo permita, Puñalada por la espalda como generador (Hemorragia cuando el objetivo te mira), Golpe fantasmal cada vez que esté disponible, y Hacer picadillo y después Eviscerar con cinco puntos, sin Ruptura. Te recuerda usar Esfumarse para otra Emboscada contra un jefe tanqueado. Elígela en lugar de la rotación integrada de pícaro recomendada si cogiste los talentos de Degollador; se aplica con Sutileza como tu árbol de talentos principal y con Degollador aprendido. Los mismos recordatorios de venenos y tiempos de reutilización que la rotación integrada recomendada. Es una alternativa a la rotación integrada de DPS de pícaro recomendada, desactivada por defecto: actívala y desactiva la otra, o súbele la prioridad.",
-- 208fc263 English: Subtlety, Garrote build (Wowhead)
[7] = "Sutileza, build de Garrote (Wowhead)",
-- 919f756d English: Wowhead's Subtlety: Premeditation and Garrote on every opener, and Vanish (then
--     Preparation) used in the rotation to open with Garrote again once the last one has run out.
--     Slice and Dice kept up, Expose Armor in groups, Rupture as the five-point finisher,
--     Hemorrhage as the only builder. This spends Vanish, your escape, on damage: choose it
--     deliberately. It applies with Subtlety as your main talent tree, Dirty Deeds talented and
--     Premeditation known. Same poison and cooldown reminders as the recommended premade. An
--     alternative to the recommended Rogue DPS premade, off by default: enable it and disable that
--     one, or raise its priority.
[8] = "La Sutileza de Wowhead: Premeditación y Garrote en cada apertura, y Esfumarse (y después Preparación) usado dentro de la rotación para volver a abrir con Garrote cuando el anterior haya expirado. Hacer picadillo siempre activo, Exponer armadura en grupo, Ruptura como remate de cinco puntos y Hemorragia como único generador. Esto gasta Esfumarse, tu vía de escape, en daño: elígela a propósito. Se aplica con Sutileza como tu árbol de talentos principal, Malas artes aprendida y Premeditación conocida. Los mismos recordatorios de venenos y tiempos de reutilización que la rotación integrada recomendada. Es una alternativa a la rotación integrada de DPS de pícaro recomendada, desactivada por defecto: actívala y desactiva la otra, o súbele la prioridad.",
-- ea331596 English: Recommended for Assassination in Midnight. In combat the game now hides your
--     bleeds, buffs, energy, cooldown times and health from addons, so this shows Blizzard's own
--     Assisted Combat suggestion (the one-button rotation, which handles the stealth opener,
--     Garrote, Rupture, Envenom, Deathmark and Kingsbane), and stops while you cast or have no
--     enemy targeted. Reminders for what it leaves out: a lethal and a non-lethal poison and
--     Stealth between pulls, Vanish when you are out of stealth in combat, Kick on an interruptible
--     cast (it lights only where the game lets the cast be read). Health is hidden on Retail, so
--     Crimson Vial is your call.
[9] = "Recomendada para Asesinato en Midnight. En combate, el juego ahora oculta a los addons tus sangrados, tus beneficios, la energía, los tiempos de reutilización y la salud, así que esta rotación muestra la propia sugerencia del Ayudante de combate de Blizzard (la rotación de un solo botón, que se encarga de la apertura desde sigilo, Garrote, Ruptura, Envenenar, Marca letal y Perdición de Reyes), y se detiene mientras lanzas o no tienes un enemigo como objetivo. Recordatorios de lo que deja fuera: un veneno letal y uno no letal y Sigilo entre combates, Esfumarse cuando estás fuera de sigilo en combate, Patada ante un lanzamiento interrumpible (solo se ilumina donde el juego permite leer el lanzamiento). La salud está oculta en Retail, así que Vial carmesí lo decides tú.",
-- 04026a9b English: Reference only, off by default: the Icy Veins and SimulationCraft order keeps
--     bleeds up by their timers, which Midnight hides in combat; energy is hidden on Retail, so its
--     energy pooling is left out. From stealth Garrote, then Ambush. Garrote in its last 30% while
--     you are not at full combo points, Rupture at 5+ in its last 30%; at 5+ combo points Coup de
--     Grace or Envenom; below, Crimson Tempest on three or more enemies, Fan of Knives on two or
--     more close by, Ambush, Mutilate. Reminders: Deathmark with both bleeds up, Kingsbane
--     alongside it, Vanish with Deathmark ready, Shiv on a Deathstalker's Mark target, Thistle Tea
--     whenever it is ready in combat, plus the shared poison, Stealth and Kick reminders.
[10] = "Solo de referencia, desactivada por defecto: el orden de Icy Veins y SimulationCraft mantiene los sangrados según sus temporizadores, y Midnight oculta esos datos en combate; la energía está oculta en Retail, así que se omite su acumulación de energía. Desde sigilo, Garrote y luego Emboscada. Garrote en su último 30 % mientras no tengas todos los puntos de combo, Ruptura con 5 o más en su último 30 %; con 5 o más puntos de combo, Golpe de gracia o Envenenar; con menos, Tempestad carmesí contra tres o más enemigos, Abanico de cuchillos contra dos o más cercanos, Emboscada, Mutilar. Recordatorios: Marca letal con ambos sangrados activos, Perdición de Reyes junto a ella, Esfumarse con Marca letal lista, Puyazo sobre un objetivo con Marca de mortacechador, Té de cardo siempre que esté listo en combate, además de los recordatorios compartidos de venenos, Sigilo y Patada.",
-- bb9cc61b English: Recommended for Outlaw in Midnight. Shows Blizzard's Assisted Combat suggestion
--     (it handles the stealth opener, Roll the Bones, Blade Flurry, Adrenaline Rush, Between the
--     Eyes and the finishers), and stops while you cast or have no enemy targeted. Reminders for
--     what it leaves out: poisons and Stealth between pulls, Vanish when you are out of stealth in
--     combat, Kick. Health is hidden on Retail, so Crimson Vial is your call. Keep It Rolling stays
--     with you: the game hides how many Roll the Bones buffs you have.
[11] = "Recomendada para Forajido en Midnight. Muestra la sugerencia del Ayudante de combate de Blizzard (se encarga de la apertura desde sigilo, A suertes, Aluvión de acero, Subidón de adrenalina, Entre ceja y ceja y los remates), y se detiene mientras lanzas o no tienes un enemigo como objetivo. Recordatorios de lo que deja fuera: venenos y Sigilo entre combates, Esfumarse cuando estás fuera de sigilo en combate, Patada. La salud está oculta en Retail, así que Vial carmesí lo decides tú. Suerte prolongada queda a tu cargo: el juego oculta cuántos beneficios de A suertes tienes.",
-- 3a3eecef English: Reference only, off by default: the Icy Veins, SimulationCraft and Wowhead
--     order reads Roll the Bones buffs, Opportunity stacks and energy, which Midnight hides in
--     combat. From stealth Ambush. One combo point short of full or more: Between the Eyes, Killing
--     Spree, Coup de Grace, Dispatch. Otherwise Ambush with Audacity, Pistol Shot at six
--     Opportunity stacks (three when low on combo points), Ambush, Sinister Strike. Reminders: Roll
--     the Bones with no roll up, Adrenaline Rush at two or fewer combo points, Blade Flurry kept up
--     on two or more enemies, Blade Rush, Preparation when Adrenaline Rush, Between the Eyes and
--     Blade Rush are all cooling. Keep It Rolling stays manual.
[12] = "Solo de referencia, desactivada por defecto: el orden de Icy Veins, SimulationCraft y Wowhead lee los beneficios de A suertes, las acumulaciones de Oportunidad y la energía, que Midnight oculta en combate. Desde sigilo, Emboscada. Con un punto de combo menos del máximo o más: Entre ceja y ceja, Asesinato múltiple, Golpe de gracia, Despachar. Si no, Emboscada con Audacia, Disparo de pistola con seis acumulaciones de Oportunidad (tres con pocos puntos de combo), Emboscada, Golpe siniestro. Recordatorios: A suertes sin ninguna tirada activa, Subidón de adrenalina con dos puntos de combo o menos, Aluvión de acero mantenido contra dos o más enemigos, Carga de hojas, Preparación cuando Subidón de adrenalina, Entre ceja y ceja y Carga de hojas están todos en reutilización. Suerte prolongada sigue siendo manual.",
-- 96f6f8ea English: Recommended for Subtlety in Midnight. Shows Blizzard's Assisted Combat
--     suggestion (it handles the stealth opener, Shadow Blades, Goremaw's Bite, Shadow Dance,
--     Secret Technique and the finishers), and stops while you cast or have no enemy targeted.
--     Reminders for what it leaves out: poisons and Stealth between pulls, Kick on an interruptible
--     cast. Health is hidden on Retail, so Crimson Vial is your call.
[13] = "Recomendada para Sutileza en Midnight. Muestra la sugerencia del Ayudante de combate de Blizzard (se encarga de la apertura desde sigilo, Hojas de las Sombras, Mordedura de Buchegore, Danza de las Sombras, Técnica secreta y los remates), y se detiene mientras lanzas o no tienes un enemigo como objetivo. Recordatorios de lo que deja fuera: venenos y Sigilo entre combates, Patada ante un lanzamiento interrumpible. La salud está oculta en Retail, así que Vial carmesí lo decides tú.",
-- 5fff6443 English: Reference only, off by default: the Icy Veins and SimulationCraft order holds
--     Shadow Dance for Secret Technique and reads Shadow Dance, Darkest Night and energy, which
--     Midnight hides in combat. Stealthed before the pull: Shadowstrike. One combo point short of
--     full or more: Eviscerate with Darkest Night, Secret Technique in Shadow Dance, Coup de Grace,
--     Black Powder on three or more enemies, Eviscerate. Otherwise Shadowstrike, Shuriken Storm on
--     two or more, Gloomblade or Backstab. Reminders: Goremaw's Bite in Shadow Dance, Shadow Blades
--     with Shadow Dance ready, Shadow Dance at two or fewer (or six or more) combo points when
--     Secret Technique is ready or Shadow Blades is up, Vanish out of stealth at two or fewer combo
--     points.
[14] = "Solo de referencia, desactivada por defecto: el orden de Icy Veins y SimulationCraft reserva Danza de las Sombras para Técnica secreta y lee Danza de las Sombras, Noche cerrada y la energía, que Midnight oculta en combate. En sigilo antes de iniciar el combate: Embate de las Sombras. Con un punto de combo menos del máximo o más: Eviscerar con Noche cerrada, Técnica secreta en Danza de las Sombras, Golpe de gracia, Pólvora negra contra tres o más enemigos, Eviscerar. Si no, Embate de las Sombras, Tormenta de shuriken contra dos o más, Hoja de la penumbra o Puñalada. Recordatorios: Mordedura de Buchegore en Danza de las Sombras, Hojas de las Sombras con Danza de las Sombras lista, Danza de las Sombras con dos puntos de combo o menos (o seis o más) cuando Técnica secreta está lista o con Hojas de las Sombras en curso, Esfumarse fuera de sigilo con dos puntos de combo o menos.",
-- 797e018d English: Recommended before you choose a specialization (while the game reports the
--     Rogue's initial specialization). Highlights the spell Blizzard's Assisted Combat suggests
--     next, the one rotation advice the game still lets an addon read in Midnight combat; it waits
--     while you cast or channel. Alongside it, the reminders every Rogue premade shares, each once
--     you know its spell. When you choose a specialization at level 10, that specialization's
--     premades take over.
[15] = "Recomendada antes de elegir una especialización (mientras el juego informa de la especialización inicial del pícaro). Resalta el próximo hechizo que sugiere el Ayudante de combate de Blizzard, el único consejo de rotación que el juego aún permite leer a un addon en el combate de Midnight; espera mientras lanzas o canalizas. Junto a él, los recordatorios que comparten todas las rotaciones integradas de pícaro, cada uno cuando conoces su hechizo. Cuando elijas una especialización a nivel 10, las rotaciones integradas de esa especialización toman el relevo.",
-- 5fc6d26a English: Levels 1–60, every spec, also on Hardcore and Self-Found realms; built from
--     simulator, Icy Veins and Wowhead. From Stealth: Premeditation, Ambush with a dagger when the
--     target is not facing you, Cheap Shot solo, Garrote outside raids. In combat: Riposte, Slice
--     and Dice from one combo point when it is missing on an elite or a healthy target (renewed at
--     five points in its last three seconds), Expose Armor at five points in a group when you have
--     Improved Expose Armor 2/2 and nobody Sunders, a two-point Eviscerate on a target about to
--     die, otherwise Eviscerate at five and no builder past five. The builder follows what you
--     know: Ghostly Strike and Hemorrhage outside raids, Backstab with a dagger when the target is
--     not facing you, else Sinister Strike. Reminders: poisons on each weapon (Deadly on an
--     off-hand weapon when carried), Kick, Thistle Tea, Blade Flurry and Adrenaline Rush on elites
--     or two enemies with Slice and Dice up, Cold Blood at five, Evasion solo when hurt. Vanish,
--     Gouge, Preparation, Kidney Shot and racials are listed off; Feint, Sprint, Blind, Sap and
--     positioning stay with you.
[16] = "Niveles 1–60, todas las especializaciones, también en reinos Hardcore y en modo de opción personal; basada en simulador, Icy Veins y Wowhead. Desde sigilo: Premeditación, Emboscada con una daga cuando el objetivo no te mira, Golpe bajo en solitario y Garrote fuera de bandas. En combate: Estocada, Hacer picadillo desde un punto de combo cuando falta sobre un élite o un objetivo con mucha salud (renovado con cinco puntos en sus tres últimos segundos), Exponer armadura con cinco puntos en grupo cuando tienes Exponer armadura mejorado 2/2 y nadie usa Hender armadura, un Eviscerar de dos puntos sobre un objetivo a punto de morir y, si no, Eviscerar con cinco y ningún generador por encima de cinco. El generador depende de lo que conozcas: Golpe fantasmal y Hemorragia fuera de bandas, Puñalada con una daga cuando el objetivo no te mira y, si no, Golpe siniestro. Recordatorios: venenos en cada arma (Veneno mortal en un arma de la mano secundaria si la llevas), Patada, Té de cardo, Ráfaga con espada y Subidón de adrenalina contra élites o dos enemigos con Hacer picadillo activo, Sangre fría con cinco y Evasión en solitario cuando estás herido. Esfumarse, Incapacitación, Preparación, Golpe en los riñones y los beneficios raciales aparecen desactivados; Amago, Correr, Ceguera, Zapar y el posicionamiento quedan a tu cargo.",
-- 64659ecb English: Melee DPS, five-point finishers (Warcraft Tavern)
[17] = "DPS cuerpo a cuerpo, remates de cinco puntos (Warcraft Tavern)",
-- 6e2089d2 English: Warcraft Tavern's way, an alternative to the recommended melee DPS premade, off
--     by default: enable it and disable that one, or raise its priority. Every finisher waits for
--     five combo points so Relentless Strikes refunds it. Slice and Dice is used from its second
--     rank (level 42) when missing or ending, otherwise Eviscerate; no low-point Slice, no
--     near-death Eviscerate and no Expose Armor (a warrior's Sunder covers it). Same openers,
--     builders and reminders as the recommended premade.
[18] = "El enfoque de Warcraft Tavern, una alternativa a la rotación integrada de DPS cuerpo a cuerpo recomendada, desactivada por defecto: actívala y desactiva la otra, o súbele la prioridad. Todo remate espera a cinco puntos de combo para que Golpes despiadados lo reembolse. Hacer picadillo se usa desde su segundo rango (nivel 42) cuando falta o está a punto de acabar y, si no, Eviscerar; sin Hacer picadillo con pocos puntos, sin Eviscerar sobre objetivos a punto de morir y sin Exponer armadura (lo cubre el Hender armadura de un guerrero). Las mismas aperturas, generadores y recordatorios que la rotación integrada recomendada.",
-- 1bddd98c English: Swords, swing-synced Sinister Strike (simulator)
[19] = "Espadas, Golpe siniestro sincronizado con el golpe (simulador)",
-- a0a38e03 English: The simulator "sweaty" Combat order for Sword Specialization, an alternative to
--     the recommended melee DPS premade, off by default: enable it and disable that one, or raise
--     its priority. Sinister Strike only right after a main-hand swing (2.0 seconds or more to the
--     next one, set for a 2.6–2.8 speed sword; change it in a clone), unless energy is near full or
--     the target is about to die, so the extra sword attack does not delay your swing. Eviscerate
--     at five also waits for Slice and Dice, full energy or a dying target. Otherwise as the
--     recommended premade.
[20] = "El orden de Combate «exigente» de simulador para Especialización en espada, una alternativa a la rotación integrada de DPS cuerpo a cuerpo recomendada, desactivada por defecto: actívala y desactiva la otra, o súbele la prioridad. Golpe siniestro solo justo después de un golpe de la mano principal (2,0 segundos o más hasta el siguiente, ajustado para una espada de velocidad 2,6–2,8; duplícala para cambiarlo), salvo que la energía esté casi llena o el objetivo esté a punto de morir, para que el ataque extra de espada no retrase tu golpe. Eviscerar con cinco también espera a Hacer picadillo, a tener la energía llena o a un objetivo a punto de morir. Por lo demás, como la rotación integrada recomendada.",
-- 1b2af050 English: Season of Discovery, levels 1–60 with runes as you engrave them; built from
--     simulator Phase 6, Icy Veins and Zockify Phase 8. From Stealth: Shadowstrike, Garrote in a
--     group, Ambush for a Backstab build with a dagger, Cheap Shot solo. On three or more enemies
--     fighting you: Blunderbuss, Crimson Tempest, Fan of Knives first. Then Ambush on a Cutthroat
--     proc (with a dagger), Saber Slash kept at three stacks, Poisoned Knife at four poison stacks,
--     Slice and Dice from two points (renewed from four, unless Cut to the Chase is engraved),
--     Expose Armor duty when nobody Sunders or keeps Sebacious Poison up, with Carnage engraved a
--     bleed (Crimson Tempest, else Rupture; none with Saber Slash), Envenom at five (Eviscerate
--     until you engrave it), and a builder by glove rune: Mutilate, Saber Slash, Backstab (with a
--     dagger), else Sinister Strike. Reminders: a temporary enchant on each weapon, Kick, Thistle
--     Tea, Blade Flurry, Adrenaline Rush, Cold Blood and Evasion, and with Master of Subtlety
--     engraved Vanish to renew it and Preparation.
[21] = "Temporada del Descubrimiento, niveles 1–60, con las runas a medida que las grabas; basada en la fase 6 de simulador, Icy Veins y la fase 8 de Zockify. Desde sigilo: Tenebrosa, Garrote en grupo, Emboscada para una build de Puñalada con una daga y Golpe bajo en solitario. Con tres o más enemigos luchando contra ti: primero Trabuco, Tempestad carmesí y Abanico de cuchillos. Después, Emboscada cuando se activa Degollador (con una daga), Tajo de sable mantenido en tres acumulaciones, Cuchillo envenenado con cuatro acumulaciones de veneno, Hacer picadillo desde dos puntos (renovado desde cuatro, salvo con Ir al grano grabado), Exponer armadura cuando nadie usa Hender armadura ni mantiene Veneno sebáceo, con Carnicería grabada un sangrado (Tempestad carmesí y, si no, Ruptura; ninguno con Tajo de sable), Envenenar con cinco (Eviscerar hasta que lo grabes) y un generador según la runa de guantes: Mutilar, Tajo de sable, Puñalada (con una daga) o, si no, Golpe siniestro. Recordatorios: un encantamiento temporal en cada arma, Patada, Té de cardo, Ráfaga con espada, Subidón de adrenalina, Sangre fría y Evasión, y con Maestro de la sutileza grabado, Esfumarse para renovarlo y Preparación.",
-- e2dafa09 English: Melee DPS, Rupture for Carnage (SoD, Icy Veins)
[22] = "DPS cuerpo a cuerpo, Ruptura para Carnicería (SoD, Icy Veins)",
-- 9aaebdaf English: Icy Veins' Season of Discovery order, an alternative to the recommended Season
--     of Discovery melee DPS premade, off by default: enable it and disable that one, or raise its
--     priority. Every finisher at five combo points, first Slice and Dice when missing or ending,
--     then Rupture kept up when Carnage is engraved, then Envenom; Poisoned Knife only at five
--     poison stacks; Blunderbuss or Fan of Knives on three enemies. Same openers, builders and
--     reminders as the recommended premade; Sebacious Poison duty stays with you.
[23] = "El orden de Icy Veins para la Temporada del Descubrimiento, una alternativa a la rotación integrada de DPS cuerpo a cuerpo de la Temporada del Descubrimiento recomendada, desactivada por defecto: actívala y desactiva la otra, o súbele la prioridad. Todo remate con cinco puntos de combo; primero Hacer picadillo cuando falta o está a punto de acabar, después Ruptura siempre activa cuando Carnicería está grabada y después Envenenar; Cuchillo envenenado solo con cinco acumulaciones de veneno; Trabuco o Abanico de cuchillos contra tres enemigos. Las mismas aperturas, generadores y recordatorios que la rotación integrada de la Temporada del Descubrimiento recomendada; mantener Veneno sebáceo queda a tu cargo.",
-- 0a82bcd6 English: Melee DPS, lean Envenom (SoD, Zockify)
[24] = "DPS cuerpo a cuerpo, Envenenar simplificado (SoD, Zockify)",
-- b718caf6 English: Zockify's lean Season of Discovery list, an alternative to the recommended
--     Season of Discovery melee DPS premade, off by default: enable it and disable that one, or
--     raise its priority. No bleeds and no Expose Armor. Poisoned Knife at four poison stacks,
--     Slice and Dice when missing (from two points, four with Saber Slash), Envenom at five, then
--     the glove-rune builder. The Vanish and Cold Blood burst stays with you.
[25] = "La lista simplificada de Zockify para la Temporada del Descubrimiento, una alternativa a la rotación integrada de DPS cuerpo a cuerpo de la Temporada del Descubrimiento recomendada, desactivada por defecto: actívala y desactiva la otra, o súbele la prioridad. Sin sangrados ni Exponer armadura. Cuchillo envenenado con cuatro acumulaciones de veneno, Hacer picadillo cuando falta (desde dos puntos, cuatro con Tajo de sable), Envenenar con cinco y después el generador de la runa de guantes. La ráfaga de Esfumarse y Sangre fría queda a tu cargo.",
-- a76bbe4d English: Season of Discovery tank, chosen when Just a Flesh Wound is engraved; built
--     from simulator Phase 6, Icy Veins, Zockify and Warcraft Tavern. Riposte, Main Gauche on
--     cooldown, Blade Dance from one combo point (renewed from three), Slice and Dice from three
--     (renewed from four), Fan of Knives, Crimson Tempest and Blunderbuss on three or more enemies,
--     Blunderbuss while Blade Dance is up, Eviscerate at five with both buffs up, Poisoned Knife at
--     low energy, then Saber Slash, Mutilate or Sinister Strike. Reminders: Tease in a group when
--     your target attacks someone else, Kick, Evasion below half health, Blade Flurry, Adrenaline
--     Rush, Thistle Tea and weapon poisons (the off-hand one only with an off-hand weapon).
--     Shadowstep and Sebacious Poison duty stay with you.
[26] = "Tanque de la Temporada del Descubrimiento, elegida cuando Una simple herida superficial está grabada; basada en la fase 6 de simulador, Icy Veins, Zockify y Warcraft Tavern. Estocada, Daga de guardamano cada vez que esté disponible, Danza de hojas desde un punto de combo (renovada desde tres), Hacer picadillo desde tres (renovado desde cuatro), Abanico de cuchillos, Tempestad carmesí y Trabuco contra tres o más enemigos, Trabuco mientras Danza de hojas esté activa, Eviscerar con cinco y ambos beneficios activos, Cuchillo envenenado con poca energía, y después Tajo de sable, Mutilar o Golpe siniestro. Recordatorios: Chinchar en grupo cuando tu objetivo ataca a otro, Patada, Evasión por debajo de la mitad de la salud, Ráfaga con espada, Subidón de adrenalina, Té de cardo y venenos de arma (el de la mano secundaria solo con un arma en ella). Paso de las Sombras y mantener Veneno sebáceo quedan a tu cargo.",
-- a78d028d English: Recommended for Assassination, from level 10 to 90 (simulator and Wowhead for
--     Phase 5, with Icy Veins' leveling steps). Opens from Stealth with Cheap Shot when solo,
--     otherwise Mutilate (Dispatch on Blindside, with a dagger). Keeps Slice and Dice up (Envenom
--     refreshes it from level 60) and Rupture on the target, spends five points on Envenom while
--     Rupture lasts and four points to keep the Envenom buff rolling when you do not have
--     Anticipation, then Marked for Death, Dispatch below 35% or on Blindside (it needs a dagger in
--     the main hand), and Mutilate. Against four or more enemies fighting you: Slice and Dice,
--     Crimson Tempest at seven, Rupture, Envenom and Fan of Knives; tabbing Rupture onto other
--     targets is up to you. Solo it adds Recuperate and a Kidney Shot when you are low. Reminders:
--     poisons, Kick, Vendetta on long fights, Shadow Blades with Vendetta, Vanish and Preparation
--     inside Vendetta, Shadowstep from range, Evasion solo. Left to you: Tricks of the Trade and
--     Expose Armor (listed but off), Feint, Sprint and positioning.
[27] = "Recomendada para Asesinato, del nivel 10 al 90 (simulador y Wowhead para la fase 5, con los pasos de subida de nivel de Icy Veins). Abre desde Sigilo con Golpe bajo en solitario y, si no, con Mutilar (Despachar con Punto ciego, con una daga). Mantiene Hacer picadillo (Envenenar lo renueva desde el nivel 60) y Ruptura en el objetivo, gasta cinco puntos en Envenenar mientras dure Ruptura y cuatro puntos para mantener activo el beneficio de Envenenar cuando no tienes Anticipación, y después Marcado para morir, Despachar por debajo del 35 % o con Punto ciego (requiere una daga en la mano principal), y Mutilar. Contra cuatro o más enemigos luchando contra ti: Hacer picadillo, Tempestad carmesí con siete, Ruptura, Envenenar y Abanico de cuchillos; extender Ruptura a otros objetivos queda a tu cargo. En solitario añade Reponerse y un Golpe en los riñones cuando tienes poca salud. Recordatorios: venenos, Patada, Vendetta en combates largos, Hojas de las Sombras con Vendetta, Esfumarse y Preparación durante Vendetta, Paso de las Sombras a distancia y Evasión en solitario. Quedan a tu cargo: Secretos del oficio y Exponer armadura (en la lista, pero desactivados), Amago, Sprint y el posicionamiento.",
-- 446abf99 English: Envenom at five (Icy Veins)
[28] = "Envenenar con cinco (Icy Veins)",
-- 584543ab English: Off by default. The Icy Veins and Method order: Vanish on cooldown for a
--     stealthed Mutilate, Vendetta on cooldown when the fight is long enough, Envenom only at five
--     points, Rupture kept up, Dispatch below 35% or on Blindside, Mutilate. Four to eight enemies:
--     Fan of Knives with Rupture at three points or more; nine or more: Fan of Knives and Envenom
--     only. The recommended Assassination premade follows the newer Phase 5 advice instead; to use
--     this one, enable it and disable the recommended one.
[29] = "Desactivada por defecto. El orden de Icy Veins y Method: Esfumarse cada vez que esté disponible para un Mutilar desde sigilo, Vendetta cada vez que esté disponible cuando el combate dure lo suficiente, Envenenar solo con cinco puntos, Ruptura siempre activa, Despachar por debajo del 35 % o con Punto ciego, y Mutilar. De cuatro a ocho enemigos: Abanico de cuchillos con Ruptura con tres puntos o más; nueve o más: solo Abanico de cuchillos y Envenenar. La rotación integrada de Asesinato recomendada sigue en cambio los consejos más recientes de la fase 5; para usar esta, actívala y desactiva la recomendada.",
-- e298e91f English: Recommended for Combat, from level 10 to 90 (Wowhead and simulator for Phase
--     5). Since the Siege of Orgrimmar patch Sinister Strike costs 50 energy, so Revealing Strike
--     is the builder and Sinister Strike is used only under Bloodlust or Heroism with Adrenaline
--     Rush (and before level 20). Opens with Cheap Shot solo, otherwise Ambush. Keeps Slice and
--     Dice up from two points and Revealing Strike on the target, spends five points only while
--     Revealing Strike is up (Slice and Dice, Rupture on a long single-target fight without Blade
--     Flurry, Eviscerate) and waits for energy at five. Against eight or more enemies: Slice and
--     Dice, Crimson Tempest and Fan of Knives. Solo it adds Recuperate and Kidney Shot. Reminders:
--     poisons, Kick, Blade Flurry on against two or more enemies and off again, Adrenaline Rush at
--     low energy with Shadow Blades, Killing Spree, Vanish and Preparation for Ambush in Deep
--     Insight, Shadowstep, Evasion solo. Left to you: Tricks of the Trade and Expose Armor (listed
--     but off), Feint and positioning behind the target for Ambush.
[30] = "Recomendada para Combate, del nivel 10 al 90 (Wowhead y simulador para la fase 5). Desde el parche del Asedio de Orgrimmar, Golpe siniestro cuesta 50 de energía, así que Golpe revelador es el generador y Golpe siniestro solo se usa bajo Ansia de sangre o Heroísmo con Subidón de adrenalina (y antes del nivel 20). Abre con Golpe bajo en solitario y, si no, con Emboscada. Mantiene Hacer picadillo desde dos puntos y Golpe revelador en el objetivo, gasta cinco puntos solo mientras Golpe revelador esté activo (Hacer picadillo, Ruptura en un combate largo contra un solo objetivo sin Aluvión de acero, Eviscerar) y espera a tener energía con cinco. Contra ocho o más enemigos: Hacer picadillo, Tempestad carmesí y Abanico de cuchillos. En solitario añade Reponerse y Golpe en los riñones. Recordatorios: venenos, Patada, activar Aluvión de acero contra dos o más enemigos y volver a desactivarlo, Subidón de adrenalina con poca energía junto con Hojas de las Sombras, Asesinato múltiple, Esfumarse y Preparación para Emboscada durante Perspicacia profunda, Paso de las Sombras y Evasión en solitario. Quedan a tu cargo: Secretos del oficio y Exponer armadura (en la lista, pero desactivados), Amago y colocarte detrás del objetivo para Emboscada.",
-- 44b84c55 English: Sinister Strike builder (Icy Veins)
[31] = "Golpe siniestro como generador (Icy Veins)",
-- 610b2100 English: Off by default, and superseded for Phase 5. The Icy Veins, Warcraft Tavern,
--     Method and wowtbc.gg order from before the Siege of Orgrimmar patch: Slice and Dice,
--     Revealing Strike kept up, five-point Rupture on a long single-target fight and Eviscerate,
--     with Sinister Strike as the builder. Same reminders and pack play as the recommended Combat
--     premade. Choose it only if you follow those guides; enable it and disable the recommended
--     one.
[32] = "Desactivada por defecto, y superada en la fase 5. El orden de Icy Veins, Warcraft Tavern, Method y wowtbc.gg de antes del parche del Asedio de Orgrimmar: Hacer picadillo, Golpe revelador siempre activo, Ruptura de cinco puntos en un combate largo contra un solo objetivo y Eviscerar, con Golpe siniestro como generador. Los mismos recordatorios y juego contra grupos de enemigos que la rotación integrada de Combate recomendada. Elígela solo si sigues esas guías; actívala y desactiva la recomendada.",
-- 972be132 English: Anticipation (Hekili)
-- Context: Name of a Built In (premade) rotation, shown in the rotation list and picker: Rogue,
--     Mists of Pandaria Classic (variant key: Combat / Hekili). Names in parentheses (guide or tool
--     such as Icy Veins, Wowhead, SimulationCraft, simulator, Hekili, Mobalytics, Warcraft Tavern)
--     are proper names and stay unchanged.
[33] = "Anticipación (Hekili)",
-- a677df00 English: Off by default. The Hekili MoP order for Combat with Anticipation: Revealing
--     Strike is the only builder, even under Bloodlust; finishers wait for Deep Insight, four
--     Anticipation charges or Shadow Blades coming back, then Slice and Dice, Rupture on one or two
--     long-lived targets, Crimson Tempest at seven enemies and Eviscerate; Slice and Dice is
--     refreshed early at 11 Bandit's Guile stacks; Fan of Knives from four enemies. It applies only
--     with Anticipation talented. Enable it and disable the recommended Combat premade to use it.
[34] = "Desactivada por defecto. El orden de Hekili para MoP para Combate con Anticipación: Golpe revelador es el único generador, incluso bajo Ansia de sangre; los remates esperan a Perspicacia profunda, a cuatro cargas de Anticipación o a que vuelva Hojas de las Sombras, y después Hacer picadillo, Ruptura sobre uno o dos objetivos que vayan a vivir mucho, Tempestad carmesí contra siete enemigos y Eviscerar; Hacer picadillo se renueva pronto con 11 acumulaciones de Astucia del bandido; Abanico de cuchillos desde cuatro enemigos. Solo se aplica con el talento Anticipación. Actívala y desactiva la rotación integrada de Combate recomendada para usarla.",
-- c2f73eb9 English: Recommended for Subtlety with Shadow Focus, from level 10 to 90 (simulator and
--     Wowhead for Phase 5). In Stealth or Shadow Dance: Premeditation, Slice and Dice before the
--     pull, finishers at five points, Ambush, Garrote. Outside: Slice and Dice; at five points
--     Slice and Dice and Rupture when they are about to drop, Eviscerate while both last; Marked
--     for Death; Hemorrhage to keep its bleed; Backstab (with a dagger) when the target is not
--     attacking you, otherwise Hemorrhage. Against three or more enemies: Slice and Dice, Crimson
--     Tempest, Eviscerate and Fan of Knives. Solo it adds Recuperate and Kidney Shot. Reminders:
--     poisons, Kick, Shadow Dance at 75 energy with Slice and Dice and Rupture up, Vanish when Find
--     Weakness is ending, Preparation, Shadow Blades outside Dance and Stealth, Shadowstep, Evasion
--     solo. Left to you: standing behind the target (RM cannot see facing), Tricks of the Trade and
--     Expose Armor (listed but off).
[35] = "Recomendada para Sutileza con Enfoque de las Sombras, del nivel 10 al 90 (simulador y Wowhead para la fase 5). En Sigilo o Danza de las Sombras: Premeditación, Hacer picadillo antes de iniciar el combate, remates con cinco puntos, Emboscada y Garrote. Fuera de ellos: Hacer picadillo; con cinco puntos, Hacer picadillo y Ruptura cuando están a punto de expirar, y Eviscerar mientras duren ambos; Marcado para morir; Hemorragia para mantener su sangrado; Puñalada (con una daga) cuando el objetivo no te está atacando y, si no, Hemorragia. Contra tres o más enemigos: Hacer picadillo, Tempestad carmesí, Eviscerar y Abanico de cuchillos. En solitario añade Reponerse y Golpe en los riñones. Recordatorios: venenos, Patada, Danza de las Sombras con 75 de energía con Hacer picadillo y Ruptura activos, Esfumarse cuando Descubrir debilidad está a punto de acabar, Preparación, Hojas de las Sombras fuera de Danza y de Sigilo, Paso de las Sombras y Evasión en solitario. Quedan a tu cargo: colocarte detrás del objetivo (RM no puede ver la orientación), Secretos del oficio y Exponer armadura (en la lista, pero desactivados).",
-- a7cbb172 English: Subterfuge (Warcraft Tavern)
-- Context: Name of a Built In (premade) rotation, shown in the rotation list and picker: Rogue,
--     Mists of Pandaria Classic (variant key: Subtlety / WarcraftTavern). Names in parentheses
--     (guide or tool such as Icy Veins, Wowhead, SimulationCraft, simulator, Hekili, Mobalytics,
--     Warcraft Tavern) are proper names and stay unchanged.
[36] = "Subterfugio (Warcraft Tavern)",
-- 01394d1f English: Chosen automatically instead of the Shadow Focus premade when your tier-1
--     talent is Subterfuge (Warcraft Tavern's build). Premeditation and Slice and Dice before the
--     pull; in Stealth, Shadow Dance or the Subterfuge linger, finishers at five points and then
--     Ambush as often as it lands. Two or three enemies: keep Rupture up and spend five points on
--     Crimson Tempest instead of Eviscerate; four or more add Fan of Knives. One target: Slice and
--     Dice, Rupture, Eviscerate, Hemorrhage for its bleed, Backstab from behind with a dagger, else
--     Hemorrhage. Shadow Dance and Vanish are reminders at 60 energy with Slice and Dice up; timing
--     them to trinket procs, as Tavern suggests, is up to you.
[37] = "Elegida automáticamente en lugar de la rotación integrada de Enfoque de las Sombras cuando tu talento del nivel 1 es Subterfugio (la build de Warcraft Tavern). Premeditación y Hacer picadillo antes de iniciar el combate; en Sigilo, Danza de las Sombras o mientras persiste Subterfugio, remates con cinco puntos y después Emboscada tantas veces como impacte. Dos o tres enemigos: mantén Ruptura y gasta cinco puntos en Tempestad carmesí en lugar de Eviscerar; con cuatro o más se añade Abanico de cuchillos. Un objetivo: Hacer picadillo, Ruptura, Eviscerar, Hemorragia por su sangrado, Puñalada por la espalda con una daga y, si no, Hemorragia. Danza de las Sombras y Esfumarse son recordatorios con 60 de energía y Hacer picadillo activo; sincronizarlos con las activaciones de abalorios, como sugiere Tavern, queda a tu cargo.",
-- 60f6bea5 English: For levels 1 to 9, or a rogue who has not chosen a specialization yet; each
--     specialization's premade takes over once you pick one. Opens from Stealth with Cheap Shot
--     when solo, Ambush or Sinister Strike; suggests Stealth out of combat; Slice and Dice from two
--     points, Recuperate and Kidney Shot when solo and hurt, Eviscerate at four points (two when
--     the target is about to die), Sinister Strike. Reminders: poisons once learned, Kick, Evasion
--     solo.
[38] = "Para los niveles 1 a 9, o un pícaro que aún no haya elegido especialización; la rotación integrada de cada especialización toma el relevo en cuanto eliges una. Abre desde Sigilo con Golpe bajo en solitario, Emboscada o Golpe siniestro; sugiere Sigilo fuera de combate; Hacer picadillo desde dos puntos, Reponerse y Golpe en los riñones en solitario y herido, Eviscerar con cuatro puntos (dos cuando el objetivo está a punto de morir) y Golpe siniestro. Recordatorios: venenos una vez aprendidos, Patada y Evasión en solitario.",
}
